import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Fast aggregate stats
    total_opp_c = 0
    total_opp_d = 0
    total_my_c = 0
    for a, b in history:
        if b == 'C':
            total_opp_c += 1
        else:
            total_opp_d += 1
        if a == 'C':
            total_my_c += 1

    total_my_d = n - total_my_c

    # Recent window (last 8)
    recent = history[-8:] if n >= 8 else history
    rn = len(recent)
    rec_opp_c = 0
    rec_opp_d = 0
    rec_my_d = 0
    for a, b in recent:
        if b == 'C':
            rec_opp_c += 1
        else:
            rec_opp_d += 1
        if a == 'D':
            rec_my_d += 1

    # Absolute always-defector detection
    if total_opp_c == 0:
        return 'D'

    # Opponent has never defected - exploit sparingly to keep them cooperating
    if total_opp_d == 0:
        if n >= 95:
            return 'D'
        # Rare probe but mostly cooperate so mutual CC continues
        if n > 25 and rng.random() < 0.12:
            return 'D'
        return 'C'

    opp_defect_rate = total_opp_d / n

    # Endgame exploitation: last rounds, defect if opponent has been lenient
    if n >= 97:
        if total_opp_c * 100 >= n * 55:
            return 'D'
        # If we've been mostly cooperated against, still exploit
        if total_opp_d > 0 and opp_last == 'C':
            return 'D'
        return 'D' if rng.random() < 0.5 else 'C'

    if n >= 90:
        # Defect more aggressively toward the end
        if total_opp_c * 100 >= n * 60:
            return 'D' if rng.random() < 0.85 else 'C'
        if opp_defect_rate < 0.35:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'D' if rng.random() < 0.5 else 'C'

    # Retaliate against sustained recent defection
    if rec_opp_d >= 6:
        # Almost always defect, tiny cooperation probe to allow recovery
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if rec_opp_d >= 3:
        # Punish, but allow occasional forgiveness
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if opp_last == 'D':
        # Tit-for-tat retaliation with forgiveness streaks
        if rec_opp_d <= 1 and total_opp_c * 100 >= n * 75:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if rec_opp_d <= 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # opp_last == 'C'
    # If we just defected and got forgiven, cooperate back
    if my_last == 'D':
        return 'C'

    # Exploit very cooperative opponents occasionally
    if opp_defect_rate < 0.12 and n > 30:
        if rng.random() < 0.18:
            return 'D'
        return 'C'

    # Against mostly-defecting opponents, lean defection
    if opp_defect_rate > 0.55:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Moderate opponent: probe occasionally and adapt
    if total_my_d > total_opp_d + 4:
        # We've been exploiting; consider cooperating to keep them in the game
        if rng.random() < 0.6:
            return 'C'
        return 'D'

    if rec_opp_c >= 6:
        return 'C'

    # Gentle probe to test for exploitation opportunities
    if n > 15 and rng.random() < 0.08:
        return 'D'

    return 'C'
